import React from 'react'
import { Routes, Route, Link } from 'react-router-dom';

function HomePageButton() {
    return (
        <Link to='/'>
            <button
                style={{
                    padding: '10px 20px',
                    fontSize: '18px',
                    backgroundColor: '#007bff',
                    color: 'white',
                    border: 'none',
                    borderRadius: '5px',
                    cursor: 'pointer',
                    whiteSpace: 'nowrap',
                    height: '50px'}}>
                Pradžia
            </button>
        </Link>
    )
}

export default HomePageButton;
